from h34 import *
M=mcq;F=tf;S=short;N=num
numberline('c3-give-take.svg',364,420,4,[(364,414,'+50'),(414,416,'+2')],'364 + 52 on a number line')
chapter(3,'maths','give-and-take','Give and Take',
 ('Kishan\'s plant nursery','Kishan runs a big plant nursery. Villagers come to take saplings, and sometimes he buys new saplings from his friend\'s village. Every time saplings come in or go out he has to add or subtract. He uses box diagrams and blocks of hundreds, tens and ones to be sure of the counts.'),
 [('Adding bigger numbers',['Kishan had 364 saplings and brought 52 more. We add 364 + 52 to find the total.','We draw a box diagram. The whole is the long box, and the two parts are 364 and 52.','We add ones first, 4 + 2 = 6. Then tens, 6 tens and 5 tens make 11 tens. 10 tens are exchanged for 1 hundred, so 1 ten is left. Then hundreds, 3 hundreds and the new hundred make 4 hundreds.','So 364 + 52 = 416 saplings, which is 4 hundreds, 1 ten and 6 ones.','On a number line we can also jump 50 from 364 to 414, and then 2 more to 416.']),
  ('Subtracting with exchange',['Kishan must send 230 saplings to a school, and he has packed 75 of them. How many more must he pack? We find 230 - 75.','We cannot take 5 ones from 0 ones, so we open one ten into 10 ones. Now we have 2 hundreds, 2 tens and 10 ones.','10 ones take away 5 ones leaves 5 ones. Now 2 tens take away 7 tens is not possible, so we open 1 hundred into 10 tens. We have 1 hundred and 12 tens.','12 tens take away 7 tens leaves 5 tens. So 230 - 75 = 155 saplings.','We can check the answer by adding: 155 + 75 = 230.']),
  ('Problems with the box diagram',['Kishan had 456 saplings and gave away 63. The box diagram shows 456 as the whole, so we subtract 456 - 63 = 393.','He had 309 and got 80 more. 309 + 80 = 389.','He has 270 herb saplings and his friend has 36. To find how many more, we compare, 270 - 36 = 234.','Words like in all, total and more than mean add. Words like left, gave away and how many more mean subtract.','When we add 100, the hundreds digit goes up by one. When we add 10, the tens digit goes up by one. When we add 1, the ones digit goes up by one.']),
  ('Exchanging things and money',['Long ago in the village Jadupur, people exchanged things based on need. 5 sacks of rice could be given for 10 sacks of vegetables because the things had different values.','Today we use money. Notes and coins have different values. A 10-rupee note can buy ten toffees or one hawa mithai, so a hawa mithai costs more than a toffee.','Five 100-rupee notes are worth one 500-rupee note, so 5 × 100 = 500.','Amounts can be made in more than one way. 55 rupees can be made with a 50-rupee note and a 5-rupee coin, or with five 10-rupee notes and a 5-rupee coin.','Add the money we give and subtract what we get back to find the change.'])],
 [('Kishan had 364 saplings and bought 52 more. How many saplings does he have?',[('Add the ones: 4 + 2 = 6.','Start from the ones.'),('Add the tens: 60 + 50 = 110, so 1 hundred and 1 ten.','Exchange 10 tens for a hundred.'),('300 + 100 + 10 + 6 = 416 saplings.','Estimate: 360 + 50 = 410. So 416 is sensible.')]),
  ('Kishan must pack 230 saplings and has packed 75. How many more?',[('Write 230 - 75.','We need the part that is missing.'),('Open a ten to get 10 ones and then a hundred to get 10 tens.','Exchange since 0 ones and 3 tens are not enough.'),('155 more saplings.','Check: 155 + 75 = 230.')]),
  ('A rupee 100 note and a rupee 20 note pay for a toy that costs 85. How much change is returned?',[('We gave 100 + 20 = 120 rupees.','Add the notes.'),('Change is 120 - 85 = 35 rupees.','Subtract the cost from the amount given.')])],
 ('Explain how you subtract 230 - 75 using hundreds, tens and ones.',['Open a ten into ten ones','Open a hundred into ten tens','Take away in each place','Check by adding back'],['Always subtract the smaller digit from the bigger','Ones and tens are the same size']),
 ['We add and subtract numbers by hundreds, tens and ones.','10 tens make 1 hundred, and 10 ones make 1 ten, and we can exchange them.','A box diagram shows the whole and its parts.','We check subtraction by adding the answer back.','Money notes and coins have values, and we can make an amount in different ways.'],
 [N('1',1,'364 + 52 = ?',416,'4 + 2 = 6 ones, 60 + 50 = 110, and 300 + 110 = 410, so 416.',[(316,'Do not forget the 100 from 10 tens'),(426,'Check the tens: 6 + 5 = 11 tens')]),
  N('2',1,'230 - 75 = ?',155,'Open a ten and a hundred. 155.',[(165,'Count again'),(145,'Check 145 + 75 = 220')]),
  N('3',1,'456 - 63 = ?',393,'456 - 60 = 396 and 396 - 3 = 393.',[(403,'456 - 63 is less than 456 - 50'),(493,'That is adding')]),
  N('4',1,'309 + 80 = ?',389,'309 + 80: 80 more makes 3 hundreds and 8 tens and 9 ones.',[(399,'Add 8 tens, not 9'),(309,'We still need to add 80')]),
  N('5',2,'270 - 36 = ?',234,'270 - 30 = 240 and 240 - 6 = 234.',[(246,'Subtract 36, not 24'),(244,'Count back 6 from 240')]),
  N('6',2,'10 tens make how many hundreds?',1,'10 tens = 100.',[(10,'10 tens is a single hundred'),(100,'That is the value in ones')]),
  N('7',2,'How many 100-rupee notes make 500 rupees?',5,'5 × 100 = 500.',[(50,'50 notes would be 5000 rupees'),(10,'10 notes = 1000 rupees')]),
  M('8',2,'Which word hints at subtraction?','left',[('total','Total means add'),('in all','In all means add')],'Left means take away.'),
  N('9',2,'A toy costs 85 rupees. You pay 100 rupees. What change do you get?',15,'100 - 85 = 15.',[(185,'We subtract, not add'),(25,'100 - 85 is 15')]),
  F('10',2,'We can make 55 rupees in more than one way.',True,'For example 50 + 5, or five 10s and a 5.'),
  N('11',3,'456 + 10 = ?',466,'Adding 10 changes the tens digit.',[(556,'That is 456 + 100'),(457,'That is 456 + 1')]),
  M('12',3,'Why did Jadupur people give different amounts when exchanging things?','Different things have different values',[('They did not know how to count','They counted well'),('They used coins','They exchanged things')],'A sack of rice is worth more than a sack of onions.')],
 svgs=[('c3-give-take','A number line from 364 to 420 with jumps of 50 and 2','Add the tens first, then the ones.')],
 keep=['add','subtract','hundreds','tens','ones'])
chapter(3,'maths','time-goes-on','Time Goes On',
 ('Hetal\'s calendar and clock','Hetal looks at a calendar on the wall and a clock in the kitchen. The calendar tells her the day and date, and the clock tells her the time. She learns that a week has seven days, a year has twelve months and her birthday comes round once each year. She also reads the time on a clock.'),
 [('Days, weeks and months',['A week has seven days. They are Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday, and then the week starts again.','A year has twelve months. The names of the months and their order stay the same every year.','A calendar shows each month in rows of weeks. We can find the day for any date by looking at the row and column.','In July 2024, Monday is the first day and Sundays fall on the 7th, 14th, 21st and 28th. Thursdays fall on the 4th, 11th, 18th and 25th.','Three days after Monday 22 July is Thursday 25 July.']),
  ('Years and festivals',['A year has 365 days. That is 52 full weeks and 1 extra day, so a year does not have 53 full weeks.','Some months have 31 days, some have 30 and February has fewer than 30.','The days of the week and the dates of festivals change from year to year. Some festivals such as Independence Day, Republic Day and Christmas fall on the same date every year, while many others change.','Your birthday comes once every year on the same date.']),
  ('Age and birth certificate',['A birth certificate tells us a person\'s name, date and place of birth and the names of the parents.','Bincy\'s certificate says she was born on 02/05/2015. That is the second of May in the year 2015.','On 2 May 2025 she will be 10 years old, and on 2 May 2030 she will be 15. Her eighth birthday was on 2 May 2023.','The certificate was made on 18 May 2015, which is 16 days after her birth.','Age puzzles use these facts. If Hetal is twice as old as her brother and also 10 years older than him, then her brother is 10 years old and Hetal is 20.']),
  ('Reading the clock',['A clock has a short hour hand and a long minute hand. The hour hand tells the hour and the minute hand tells the minutes.','When the minute hand points to 12 it is an o\'clock time such as 7 o\'clock. When the minute hand points to 3 it is quarter past, 15 minutes after the hour. When it points to 6 it is half past, 30 minutes after the hour.','Hetal starts breakfast at 7:00 and finishes at 7:15, so breakfast takes 15 minutes. We find the time taken by seeing how far the minute hand moved.','We can write time in numbers as 8:15, which is quarter past 8, and 8:30, which is half past 8.'])],
 [('What day is 25 July 2024 if 22 July 2024 is a Monday?',[('From the 22nd to the 25th is 3 days.','25 - 22 = 3.'),('Monday + 3 days: Tuesday, Wednesday, Thursday.','Count on the weekdays.'),('So 25 July is a Thursday.','Check with the calendar of July 2024.')]),
  ('How old will Bincy be on 2 May 2025 if she was born on 2 May 2015?',[('From 2015 to 2025 is 10 years.','Subtract the years: 2025 - 2015 = 10.'),('The birthday has just come.','The date 2 May is the same.'),('She will be 10 years old.','Check: 10 birthdays have passed.')]),
  ('Hetal started breakfast at 7:00 and finished at 7:15. How long did she take?',[('The minute hand moved from 12 to 3.','Look at the clock.'),('From 12 to 3 is 15 minutes.','Each number is 5 minutes.'),('She took 15 minutes.','Quarter of an hour.')])],
 ('Explain how to read 8:30 on a clock.',['Hour hand between 8 and 9','Minute hand points to 6','Half past 8','30 minutes after 8'],['The hour hand is long','Minute hand at 6 means 6 minutes']),
 ['A week has 7 days and a year has 12 months and 365 days.','A calendar helps us find days and dates and count the days between dates.','We find age by counting how many birthdays have passed.','The short hand is the hour hand and the long hand is the minute hand.','Quarter past is 15 minutes after the hour and half past is 30 minutes after.'],
 [N('1',1,'How many days are in a week?',7,'Monday to Sunday.',[(5,'Five weekdays, but there are weekend days too'),(6,'Count Saturday and Sunday')]),
  N('2',1,'How many months are in a year?',12,'January to December.',[(10,'Count all the months'),(11,'Count December')]),
  N('3',1,'How many days are in a normal year?',365,'52 weeks and 1 day.',[(360,'12 × 30 is 360, but months have different days'),(366,'That is a leap year')]),
  M('4',1,'Which hand is longer?','Minute hand',[('Hour hand','Hour hand is short'),('Both same','They differ')],'The minute hand is longer.'),
  M('5',2,'When the minute hand points to 6, it is?','Half past',[('Quarter past','That is at 3'),('O\'clock','That is at 12')],'6 is 30 minutes.'),
  N('6',2,'How many minutes is a quarter past?',15,'A quarter of 60 minutes.',[(30,'That is half past'),(45,'That is quarter to')]),
  N('7',2,'July 2024 started on a Monday. How many Sundays were there?',4,'7th, 14th, 21st and 28th.',[(5,'The fifth Sunday would be the 35th'),(3,'Count again')]),
  S('8',2,'What day comes three days after Monday 22 July?',['thursday','Thursday'],'Tuesday, Wednesday, Thursday.'),
  N('9',2,'Bincy was born on 2 May 2015. How old on 2 May 2025?',10,'2025 - 2015 = 10.',[(11,'Count only complete years'),(9,'The birthday has come')]),
  F('10',2,'A year has 53 full weeks.',False,'A year has 52 full weeks and 1 extra day.'),
  N('11',3,'Breakfast from 7:00 to 7:15 takes how many minutes?',15,'The minute hand moves from 12 to 3.',[(5,'12 to 3 is three numbers'),(30,'30 would be to 6')]),
  F('12',3,'Independence Day changes its date every year.',False,'It falls on 15 August every year.')],
 keep=['calendar','clock','minute hand','hour hand'])
